type ProgramView=Program & {op?:OP;product?:Product}
function ProgramacaoTimeline({programs,machines,molds,employees,onProgram}:{programs:ProgramView[];machines:Machine[];molds:Molde[];employees:Employee[];onProgram:(opId?:string)=>void}){
 const active=programs.filter(p=>p.status?.toLowerCase()!=='cancelada'&&p.inicio_planejado&&p.fim_planejado)
 const base=active.length?new Date(Math.min(...active.map(p=>new Date(p.inicio_planejado).getTime()))):new Date()
 base.setHours(0,0,0,0)
 const horizon=14
 const days=Array.from({length:horizon},(_,i)=>{const d=new Date(base);d.setDate(base.getDate()+i);return d})
 const endH=new Date(base);endH.setDate(base.getDate()+horizon)
 const totalMs=endH.getTime()-base.getTime()
 const machineStats=machines.map(m=>{const ps=active.filter(p=>p.maquina_id===m.id);const pieces=ps.reduce((s,p)=>s+Number(p.quantidade_planejada||0),0);const moldCount=new Set(ps.map(p=>p.molde_id).filter(Boolean)).size;const hours=ps.reduce((s,p)=>s+Math.max(0,(new Date(p.fim_planejado).getTime()-new Date(p.inicio_planejado).getTime())/3600000),0);const shiftHours=ps.reduce((s,p)=>s+Math.max(1,Number(p.horas_turno||8))*Math.max(1,Number(p.turnos||1)),0)/Math.max(1,ps.length);return{m,ps,pieces,moldCount,hours,days:hours/Math.max(1,shiftHours)} })
 const fmtDay=(d:Date)=>d.toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'}).replace('.','')
 const durationDays=(p:ProgramView)=>Math.max(.01,(new Date(p.fim_planejado).getTime()-new Date(p.inicio_planejado).getTime())/86400000)
 const leftPct=(p:ProgramView)=>Math.max(0,Math.min(100,(new Date(p.inicio_planejado).getTime()-base.getTime())/totalMs*100))
 const widthPct=(p:ProgramView)=>Math.max(.8,Math.min(100-leftPct(p),(new Date(p.fim_planejado).getTime()-new Date(p.inicio_planejado).getTime())/totalMs*100))
 const moldName=(id:string|null|undefined)=>molds.find(m=>m.id===id)?.codigo||'sem molde'
 const empName=(id:string|null|undefined)=>employees.find(e=>e.id===id)?.nome||'â€”'
 return <section className="pcp-timeline-wrap">
  <div className="pcp-section-toolbar"><div><strong>ProgramaÃ§Ã£o visual da fÃ¡brica</strong><small>Os dias ficam no topo e cada barra mostra o que estÃ¡ programado em cada mÃ¡quina.</small></div><button className="primary-v2" onClick={()=>onProgram()}><InlineIcon name="Plus" size={17}/> Programar OP</button></div>
  <div className="pcp-planning-strip"><div><strong>O PCP calcula carga, nÃ£o sÃ³ datas.</strong><span>Quantidade â€¢ ciclo â€¢ cavidades â€¢ setup â€¢ turnos â€¢ eficiÃªncia â€¢ molde â€¢ operadores.</span></div><b>{active.reduce((s,p)=>s+Number(p.quantidade_planejada||0),0).toLocaleString('pt-BR')} peÃ§as programadas</b><b>{new Set(active.map(p=>p.molde_id).filter(Boolean)).size} moldes</b><b>{active.length} blocos</b></div>
  <div className="pcp-timeline-card"><div className="pcp-timeline-scroll"><div className="pcp-timeline-grid grid min-w-[1560px] grid-cols-[190px_repeat(14,minmax(92px,1fr))]">
   <div className="pcp-timeline-corner">MÃQUINA</div>{days.map(d=><div className="pcp-day-head" key={d.toISOString()}><strong>{fmtDay(d)}</strong><small>{d.toLocaleDateString('pt-BR',{year:'numeric'})}</small></div>)}
   {machines.map(m=>{const stat=machineStats.find(x=>x.m.id===m.id)!;return <div className="pcp-machine-row" key={m.id}><div className="pcp-machine-label"><strong>{m.codigo}</strong><span>{m.nome}</span><small>{stat.ps.length} blocos â€¢ {stat.pieces.toLocaleString('pt-BR')} peÃ§as â€¢ {stat.moldCount} moldes â€¢ {stat.hours.toFixed(1)} h</small></div><div className="pcp-machine-track col-span-14 col-start-2"><div className="pcp-day-lines">{days.map(d=><i key={d.toISOString()}/>)}</div>{stat.ps.map((p:ProgramView,i:number)=><button key={p.id} className={`pcp-gantt-bar absolute ${ganttLeftBucket(leftPct(p))} ${ganttWidthBucket(widthPct(p))} ${ganttTopBucket(i)}`} onClick={()=>onProgram(p.ordem_producao_id||undefined)} title={`${p.op?.numero_op||'OP'} â€¢ ${p.product?.codigo||'produto'} â€¢ ${moldName(p.molde_id)} â€¢ ${durationDays(p).toFixed(1)} dias â€¢ ${Number(p.quantidade_planejada||0).toLocaleString('pt-BR')} peÃ§as`}><strong>{p.op?.numero_op||'OP'}</strong><span>{p.product?.codigo||'produto'} â€¢ {moldName(p.molde_id)}</span><small>{durationDays(p).toFixed(1)} d â€¢ {Number(p.quantidade_planejada||0).toLocaleString('pt-BR')} pÃ§ â€¢ {empName(p.operador_frente_id)} / {empName(p.operador_atras_id)}</small></button>)}</div></div>})}
  </div></div></div>
  <div className="pcp-capacity-summary"><div><strong>Resumo por mÃ¡quina</strong><span>Mostra quantos dias a prensa fica ocupada, quantos moldes passam por ela e quantas peÃ§as estÃ£o programadas.</span></div>{machineStats.map(s=><article key={s.m.id}><strong>{s.m.codigo}</strong><b>{s.days.toFixed(1)} dias</b><span>{s.hours.toFixed(1)} h ocupadas</span><span>{s.moldCount} moldes â€¢ {s.pieces.toLocaleString('pt-BR')} peÃ§as</span></article>)}</div>
  <Table title="Detalhamento das programaÃ§Ãµes" cols={['OP','MÃ¡quina','Molde','Operadores frente / atrÃ¡s','InÃ­cio','Fim','Dias','PeÃ§as','Ciclo','Cav.','Setup','Status']} rows={active.map((p:ProgramView)=>[p.op?.numero_op||'â€”',machines.find(m=>m.id===p.maquina_id)?.codigo||'â€”',moldName(p.molde_id),empName(p.operador_frente_id)+' / '+empName(p.operador_atras_id),new Date(p.inicio_planejado).toLocaleString('pt-BR'),new Date(p.fim_planejado).toLocaleString('pt-BR'),durationDays(p).toFixed(1),Number(p.quantidade_planejada||0),Number(p.ciclo_seg||0),Number(p.cavidades_ativas||1),Number(p.setup_min||0),p.status])} search="" setSearch={()=>{}}/>
 </section>
}

function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){
 return <div className="pcp-modal-backdrop" role="dialog" aria-modal="true"><div className="pcp-modal"><div className="pcp-modal-head"><h2>{title}</h2><button className="pcp-modal-close" onClick={onClose} aria-label="Fechar"><InlineIcon name="X" size={20}/></button></div>{children}</div></div>
}

function NovaOPScreen({orders,orderItems,products,clients,machines,fichas,fitems,fichaOps,onCancel,onSave,busy,form,setForm}:{orders:Order[];orderItems:OrderItem[];products:Product[];clients:Client[];machines:Machine[];fichas:Ficha[];fitems:FItem[];fichaOps:FichaOp[];onCancel:()=>void;onSave:(e:FormEvent)=>void;busy:boolean;form:NovaOPForm;setForm:React.Dispatch<React.SetStateAction<NovaOPForm>>}){const product=products.find(p=>p.id===form.produto_id);const ficha=fichas.find(f=>f.produto_id===form.produto_id);const materials=ficha?fitems.filter(i=>i.ficha_id===ficha.id):[];const route=ficha?fichaOps.filter(o=>o.ficha_id===ficha.id).sort((a,b)=>a.sequencia-b.sequencia):[];const qty=Number(form.quantidade||0);return <form className="pcp-newop" onSubmit={onSave}><article className="pcp-newop-card"><header><b>1</b><strong>DADOS BÃSICOS DA ORDEM</strong></header><div className="pcp-newop-grid"><label>NÂº da OP<input value="SerÃ¡ gerado automaticamente" disabled/></label><label>Data de EmissÃ£o<input type="date" value={form.data_emissao} onChange={e=>setForm(v=>({...v,data_emissao:e.target.value}))}/></label><label>Status<select value={form.status} onChange={e=>setForm(v=>({...v,status:e.target.value}))}><option value="pendente">Pendente</option><option value="planejada">Planejada</option><option value="aguardando_pcp">Aguardando PCP</option></select></label><label className="wide">Pedido de venda de origem *<select required value={form.pedido_venda_id} onChange={e=>{const order=orders.find(x=>x.id===e.target.value);setForm(v=>({...v,pedido_venda_id:e.target.value,cliente_id:order?.cliente_id||'',produto_id:'',quantidade:''}))}}><option value="">Selecione um pedido real de Vendas</option>{orders.filter(order=>!['cancelado','cancelada','rejeitado','rejeitada'].includes(String(order.status).toLowerCase())).map(order=><option key={order.id} value={order.id}>PV-{order.numero} · {order.status}</option>)}</select><small>O banco gera o número interno da OP e mantém o vínculo com este pedido.</small></label><EntityCodeLookup label="Produto do pedido *" value={form.produto_id} required records={products.filter(p=>orderItems.some(item=>item.pedido_id===form.pedido_venda_id&&item.produto_id===p.id))} onChange={value=>setForm(v=>({...v,produto_id:value}))} onSelect={p=>{const orderedQty=orderItems.filter(item=>item.pedido_id===form.pedido_venda_id&&item.produto_id===p.id).reduce((sum,item)=>sum+Number(item.quantidade||0),0);setForm(v=>({...v,produto_id:p.id,quantidade:orderedQty>0?String(orderedQty):v.quantidade}))}} helper={form.pedido_venda_id?'Produto limitado aos itens do pedido selecionado.':'Selecione primeiro o pedido de venda.'}/><EntityCodeLookup label="Cliente" value={form.cliente_id} records={clients} onChange={value=>setForm(v=>({...v,cliente_id:value}))} onSelect={x=>setForm(v=>({...v,cliente_id:x.id}))} helper="Digite o cÃ³digo do cliente; use a lupa somente quando precisar consultar."/><label>Prioridade<select value={form.prioridade} onChange={e=>setForm(v=>({...v,prioridade:e.target.value}))}><option value="ALTA">Alta</option><option value="REGULAR">Regular</option><option value="BAIXA">Baixa</option></select></label><label>Quantidade<input required type="number" min="0.0001" step="any" value={form.quantidade} onChange={e=>setForm(v=>({...v,quantidade:e.target.value}))}/></label><label>Data prevista<input type="date" value={form.data_prevista} onChange={e=>setForm(v=>({...v,data_prevista:e.target.value}))}/></label><label className="wide">ObservaÃ§Ãµes<textarea rows={2} value={form.observacoes} onChange={e=>setForm(v=>({...v,observacoes:e.target.value}))}/></label></div></article><article className="pcp-newop-card"><header><b>2</b><strong>MATÃ‰RIAS-PRIMAS NECESSÃRIAS â€” EXPLOSÃƒO DE MATERIAIS / BOM</strong></header><div className="pcp-newop-help">{product?<>Produto selecionado: <strong>{product.codigo} â€” {product.nome}</strong> â€¢ Ficha tÃ©cnica {ficha?'v'+ficha.versao:'nÃ£o cadastrada'}. Quantidade da OP: <strong>{qty.toLocaleString('pt-BR')}</strong>.</>:<>Selecione o produto para calcular a necessidade pela ficha tÃ©cnica ativa.</>}</div><table className="pcp-newop-table"><thead><tr><th>Item</th><th>Qtd. necessÃ¡ria</th><th>Estoque disponÃ­vel</th><th>SituaÃ§Ã£o</th></tr></thead><tbody>{materials.map(i=>{const p=products.find(x=>x.id===i.componente_id);const need=Number(i.quantidade)*qty*(1+Number(i.perda_percentual||0)/100);const stock=Number(p?.estoque_atual||0);return <tr key={i.id}><td>{p?.codigo||'â€”'} â€” {p?.nome||'Componente nÃ£o localizado'}</td><td>{need.toLocaleString('pt-BR')} {i.unidade_medida||'UN'}</td><td>{stock.toLocaleString('pt-BR')} {i.unidade_medida||'UN'}</td><td className={stock>=need?'pcp-newop-ok':'pcp-newop-warn'}>{stock>=need?'OK':'FALTA'}</td></tr>})}{!materials.length&&<tr><td colSpan={4}>Nenhuma estrutura BOM real cadastrada para o produto selecionado.</td></tr>}</tbody></table></article><article className="pcp-newop-card"><header><b>3</b><strong>ROTEIRO DE PRODUÃ‡ÃƒO â€” FLUXO DE MÃQUINAS</strong></header><div className="pcp-newop-route">{route.map(o=>{const m=machines.find(x=>x.id===o.maquina_id);return <div className="pcp-newop-route-row" key={o.id}><b>Seq {o.sequencia}</b><strong>{o.operacao}</strong><span>Setup: {Number(o.setup_min||0).toLocaleString('pt-BR')} min â€¢ Ciclo: {Number(o.ciclo_seg||0).toLocaleString('pt-BR')} s</span><span>C.T.: {m?.codigo||'NÃ£o definido'}</span></div>})}{!route.length&&<div className="pcp-newop-help">Nenhum roteiro real cadastrado na ficha tÃ©cnica deste produto.</div>}</div></article><article className="pcp-newop-card"><header><b>4</b><strong>DESTINO DA INFORMAÃ‡ÃƒO</strong></header><div className="pcp-newop-actions"><button type="button" onClick={onCancel}>âœ• Cancelar</button><button className="primary" disabled={busy} type="submit">ðŸ’¾ {busy?'SALVANDOâ€¦':'SALVAR E GERAR OP'}</button></div></article></form>}
function Table({title,cols,rows,search,setSearch}:{title:string;cols:string[];rows:(string|number)[][];search:string;setSearch:(v:string)=>void}){
 return <section className="crud-list"><div className="crud-list-head"><div><strong>{title}</strong><small>{rows.length} registros</small></div><div className="module-search"><InlineIcon name="Search" size={16}/><input placeholder="Pesquisar..." value={search} onChange={e=>setSearch(e.target.value)}/></div></div><div className="crud-table-wrap"><table><thead><tr>{cols.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{String(v??'â€”')}</td>)}</tr>)}{!rows.length&&<tr><td colSpan={cols.length} className="crud-empty">Nenhum registro encontrado.</td></tr>}</tbody></table></div></section>
}
